def run(graph, query):
    indeg, adj = build_indegree(graph)        # adj[u] = u's downstream
    ready = deque(n for n in graph.nodes if indeg[n] == 0)
    done, failed, ran = {}, set(), 0

    while ready:
        n = ready.popleft()
        ran += 1
        try:
            with slot(graph.max_parallel_nodes):      # concurrency cap
                done[n.id] = call_with_retry(n, bind(n.args_from, done, query))
        except NodeFailed:
            failed.add(n.id)
            propagate(n, graph, adj, indeg, ready, done)
            continue
        release(n, adj, indeg, ready)

    if ran < len(graph.nodes) and not failed:
        raise CycleError(stranded(graph, ran))  # stranded with no failure => a cycle

def release(n, adj, indeg, ready):
    for v in adj[n.id]:
        indeg[v] -= 1
        if indeg[v] == 0:
            ready.append(v)

def call_with_retry(n, args):
    key = "%s:%s" % (run_id, n.id)             # same key across attempts
    for attempt in range(n.retry.max_attempts):
        try:
            return n.kind.invoke(args, idempotency_key=key)
        except Retryable:
            sleep(n.retry.backoff(attempt))
    raise NodeFailed(n)

def propagate(n, graph, adj, indeg, ready, done):
    policy = graph.policy_of(n)                # skip | degrade | fail_graph
    if policy == "fail_graph":
        raise GraphFailed(n)
    if policy == "degrade":
        done[n.id] = graph.placeholder_of(n)
    release(n, adj, indeg, ready)              # unblock downstream either way

