# startup: the listing stays resident, bodies do not
def system_prompt(skills):
    listing = [{"name": s.name,
                "description": s.description[:1536]}
               for s in skills]
    return SYSTEM + json.dumps(listing)

# main loop: injection point is right before each model call
def run(question, skills, tools):
    msgs = [user(question)]
    while True:
        out = model(system_prompt(skills),
                    tools + [read_skill], msgs)
        if out.calls("read_skill"):            # hit: body enters context
            msgs.append(body(skills[out.name]))
            continue
        if out.calls_tool():
            msgs.append(execute(out, tools))   # execution stays in tools
            continue
        return out.text

import httpx
from openai import OpenAI

MODEL = OpenAI(
    timeout=httpx.Timeout(60.0, connect=3.0, read=20.0),
    max_retries=1,
)

def run_turn(msgs, tools, max_tool_calls=6):
    for _ in range(max_tool_calls):
        resp = MODEL.chat.completions.create(
            model=MODEL_ID, messages=msgs, tools=tools, stream=True)
        step = consume(resp)
        if not step.tool_calls:
            return step.text
        msgs += execute(step.tool_calls)
    return degraded_answer(msgs)

class OrderArgs(BaseModel):
    order_id: str = Field(pattern=r"^[A-Z0-9]{8,14}$")

ORDER_SQL = ("SELECT status, shipped_at, carrier "
             "FROM v_order_agent WHERE order_id = :oid LIMIT 50")

@tool(args_schema=OrderArgs)
def lookup_order(raw: dict) -> dict:
    for poison in ("sql", "query", "statement"):
        if poison in raw:
            audit.reject(tool="lookup_order", reason="raw_sql")
            raise ToolArgumentError("only order_id is accepted")
    if set(raw) - set(OrderArgs.model_fields):
        raise ToolArgumentError("unknown argument")
    return shape(repo.fetch(ORDER_SQL, {"oid": raw["order_id"]}))

def shape(rows, limit=50):
    truncated = len(rows) > limit
    return {
        "ok": True,
        "rows": rows[:limit],
        "row_count": min(len(rows), limit),
        "truncated": truncated,
        "cursor": rows[limit - 1]["order_id"] if truncated else None,
    }

