type StreamEvent =
  | { type: "start";       turnId: string; steps: { id: string; title: string }[] }
  | { type: "delta";       text: string }
  | { type: "tool_call";   callId: string; name: string; arguments: unknown }
  | { type: "tool_result"; callId: string; ok: boolean; error?: string }
  | { type: "step";        stepId: string;
      status: "pending" | "running" | "done" | "failed" }
  | { type: "error";       code: string; message: string; retryable: boolean }
  | { type: "done";        finishReason: string; stopped?: boolean };

function onEvent(raw: Record<string, string>) {
  const e = parse(raw) as StreamEvent;
  switch (e.type) {
    case "delta": append(e.text); break;
    case "tool_call": openCollapsedCard(e); break;
    case "step": markStep(e.stepId, e.status); break;
    case "done": finalize(e); break;
    default: break; // unknown type: ignore, never throw
  }
}

