MAX_RETRY = 1

def ask_structured(client, messages, schema, business_rules):
    last_err = None
    for _ in range(MAX_RETRY + 1):
        req = list(messages)
        if last_err:
            req.append({"role": "user",
                        "content": "Previous reply failed validation: " + last_err})
        r = client.chat.completions.create(
            model=DEPLOYMENT,
            messages=req,
            response_format={"type": "json_schema", "json_schema": schema},
            max_tokens=800,
        )
        choice = r.choices[0]
        if choice.finish_reason == "length":
            break  # truncated: feeding the error back will not help
        try:
            data = json.loads(choice.message.content)
            jsonschema.validate(data, schema)   # grammar
            business_rules(data)                # enum member, id exists, date parses
            return data
        except Exception as exc:
            last_err = str(exc)
    emit_event("agent.output_format_degraded", error=last_err)
    return {"status": "plain_text", "text": ask_plain(client, messages)}
